CREATE TABLE atlys_dataset.saved_method_used (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop; web = latter two', `os` LowCardinality(String) DEFAULT '' COMMENT '6.9% empty (mostly android), bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `city` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across express_checkout_* stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination, ISO-2 upper, 14 values', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, geoip_country_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'saved_method_used: saved instrument loaded, step 3 of express funnel (spec: Express Checkout)'
CREATE TABLE atlys_dataset.express_checkout_selected (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop; web = latter two', `os` LowCardinality(String) DEFAULT '' COMMENT '6.9% empty (mostly android), bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `city` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across express_checkout_* stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination, ISO-2 upper, 14 values', `saved_method_type` LowCardinality(String) COMMENT 'card/upi/wallet, PM adoption-by-method cut', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (saved_method_type, device_type, geoip_country_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'express_checkout_selected: user taps Express, step 2 of express funnel (spec: Express Checkout)'
CREATE TABLE atlys_dataset.express_checkout_shown (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop; web = latter two', `os` LowCardinality(String) DEFAULT '' COMMENT '6.8% empty (mostly android), bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `city` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across express_checkout_* stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination, ISO-2 upper, 14 values', `eligible` UInt8 COMMENT 'express eligibility flag, constant 1 in sample' CODEC(T64, ZSTD(1)), `shown_amount` Decimal(18, 2) COMMENT 'displayed checkout amount, range 1502-9000', `currency` LowCardinality(String) COMMENT 'shown_amount currency, never sum across currencies') ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, geoip_country_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'express_checkout_shown: button rendered, step 1 of express funnel (spec: Express Checkout)'
CREATE TABLE atlys_dataset.express_payment_confirmed (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop; web = latter two', `os` LowCardinality(String) DEFAULT '' COMMENT '7.4% empty (mostly android), bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `city` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across express_checkout_* stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination, ISO-2 upper, 14 values', `payment_amount` Decimal(18, 2) COMMENT 'confirmed payment amount, range 1509-8997', `payment_currency` LowCardinality(String) COMMENT 'payment_amount currency, never sum across currencies', `payment_latency_ms` UInt16 COMMENT 'client-measured pay latency ms, range 607-3999' CODEC(T64, ZSTD(1)), INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, os, geoip_country_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'express_payment_confirmed: payment succeeds, final step of express funnel (spec: Express Checkout)'
CREATE TABLE atlys_dataset.otp_entered (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop; web = latter two', `os` LowCardinality(String) DEFAULT '' COMMENT '6.9% empty (mostly android), bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `city` LowCardinality(String) COMMENT 'geo segment cut, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across express_checkout_* stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'trip destination, ISO-2 upper, 14 values', `otp_attempts` UInt8 COMMENT 'attempts to enter OTP, range 1-3' CODEC(T64, ZSTD(1)), `otp_success` UInt8 COMMENT 'OTP verified flag, 0 or 1' CODEC(T64, ZSTD(1)), INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, os, geoip_country_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'otp_entered: OTP submitted, step 4 of express funnel (spec: Express Checkout)'